<h2>Корзина</h2><?php if ($flash): ?><p><?= e($flash) ?></p><?php endif; ?><?php if (!$rows): ?><p>Корзина пуста.</p><?php else: ?><table><tr><th>Товар</th><th>Количество</th><th>Сумма</th><th>Действия</th></tr><?php foreach ($rows as $row): ?><tr><td><?= e($row['product']->name) ?></td><td><?= $row['qty'] ?></td><td><?= formatPrice($row['sum']) ?> ₽</td><td><form action="/cart/add" method="post"><input type="hidden" name="product_id" value="<?= $row['product']->id ?>"><input type="number" name="qty" min="1" value="<?= $row['qty'] ?>"><button name="action" value="set">Изменить</button><button name="action" value="remove">Удалить</button></form></td></tr><?php endforeach; ?></table><p>Итого: <?= formatPrice($total) ?> ₽</p><a href="/checkout">Оформить заказ</a><?php endif; ?>
